export const meta = {
  name: 'ddcli-skill-brainstorm',
  description: 'Brainstorm genuinely useful dd-cli skills, adversarially filter, synthesize a ranked shortlist',
  phases: [
    { title: 'Ideate', detail: '5 ideators with distinct lenses' },
    { title: 'Dedup', detail: 'merge overlapping ideas' },
    { title: 'Judge', detail: 'adversarial utility test per idea' },
    { title: 'Synthesize', detail: 'ranked shortlist with rationale' },
  ],
}

const CONTEXT = `
CONTEXT — DoorDash CLI (dd-cli) v0.2.0:
A terminal tool for ordering from DoorDash, explicitly designed to be driven by AI agents (Claude Code, Cursor, Codex). macOS Apple Silicon only, waitlist-gated account.
Known command surface (documented; the tree is deeper, navigable via --help at each level):
- dd-cli login
- dd-cli search --query "sushi near me"
- dd-cli cart show --cart-uuid X | cart add-items | cart remove-item --cart-uuid X --cart-item-id N
- dd-cli order history | order reorder --order-uuid Y | order checkout-url --cart-uuid X
Checkout returns a URL for the human to pay — the agent builds the cart, human completes payment.
DoorDash ships its own minimal official skill (dd-cli-usage) that just says "navigate with --help". It auto-installs to ~/.claude/skills.

TARGET — aitmpl.com catalog (claude-code-templates repo). Component types available: skills, agents, commands, hooks, settings, and LOOPS (autonomous recurring workflows: goal + interval + stop condition, can reference other components).

THE BAR (critical): The user explicitly rejected "just order food" skills — "I can already just ask Claude to use the CLI to order me a Starbucks." A worthwhile skill must encode something Claude does NOT get for free from --help navigation: multi-step orchestration with state, persistent data/preferences, scheduling/recurrence, team coordination, budget/analytics logic, integration with other tools (calendar, Slack, git workflows), or safety guardrails with teeth. If the idea's value is "phrases a request", it fails.
`

const IDEA_SCHEMA = {
  type: 'object',
  required: ['ideas'],
  properties: {
    ideas: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'pitch', 'why_not_just_ask', 'mechanics', 'component_types', 'risks'],
        properties: {
          name: { type: 'string', description: 'kebab-case skill name' },
          pitch: { type: 'string', description: '1-2 sentence value proposition' },
          why_not_just_ask: { type: 'string', description: 'What this encodes that plain "ask Claude to use dd-cli" cannot deliver' },
          mechanics: { type: 'string', description: 'Concretely how it works: files, state, commands, loops, integration points' },
          component_types: { type: 'array', items: { type: 'string' }, description: 'skill / loop / hook / command / agent' },
          risks: { type: 'string', description: 'feasibility risks, e.g. depends on undocumented dd-cli commands' },
        },
      },
    },
  },
}

const LENSES = [
  { key: 'automation', prompt: 'LENS: Recurrence & automation. Think loops/cron: scheduled reordering, meal-prep cadences, standing lunch orders, price/availability monitoring of favorite items, auto-rebuild carts at set times so the human only clicks the checkout URL. What recurring behaviors have real value?' },
  { key: 'data-memory', prompt: 'LENS: Persistent data & preferences. Think local state files: dietary restrictions, allergies, favorite orders per context (post-gym, late-night deploy), household member preferences, order history analytics (spend per week/month, protein intake, cuisine variety), budget caps enforced before checkout. What does memory unlock?' },
  { key: 'team-social', prompt: 'LENS: Team & multi-person coordination. Think office lunch orders: collecting orders from teammates (Slack/file-based), merging into one cart, splitting costs, rotating who orders, feeding a team during an incident/on-call, ordering for a meeting from a calendar event. What coordination logic has value?' },
  { key: 'dev-workflow', prompt: 'LENS: Developer-workflow integration. This CLI lives where developers work. Think hooks and rituals: "ship it burrito" on merged PR, food during long CI runs or incident response, deadline crunch fuel, pairing with claude-code-templates hooks/loops ecosystem. Also: skills that help OTHER developers build ON dd-cli (testing agent-driven ordering safely, sandboxed dry-runs). What integrations are genuinely useful vs gimmicks?' },
  { key: 'guardrails', prompt: 'LENS: Safety, budget & guardrails. The CLI spends real money via an AI agent. Think: spend budgets with hard limits, cart-diff review before checkout (like git diff for food), duplicate-order detection, allergy safety verification against menu items, approval workflows, audit log of every agent-initiated order. What guardrails would make people TRUST agent ordering enough to use it?' },
]

phase('Ideate')
log('Fanning out 5 ideators with distinct lenses...')
const rounds = await parallel(LENSES.map(l => () =>
  agent(`${CONTEXT}\n\n${l.prompt}\n\nPropose 3-5 skill/component ideas through this lens ONLY. Every idea must pass the bar above — be brutally honest in "why_not_just_ask"; if you cannot articulate it, drop the idea. Prefer ideas buildable on the DOCUMENTED command surface; flag any that need undocumented commands as risky. Return structured output.`,
    { label: `ideate:${l.key}`, phase: 'Ideate', schema: IDEA_SCHEMA })
))

const allIdeas = rounds.filter(Boolean).flatMap(r => r.ideas)
log(`${allIdeas.length} raw ideas collected. Deduplicating...`)

phase('Dedup')
const DEDUP_SCHEMA = {
  type: 'object',
  required: ['merged'],
  properties: {
    merged: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'pitch', 'why_not_just_ask', 'mechanics', 'component_types', 'risks', 'merged_from'],
        properties: {
          name: { type: 'string' }, pitch: { type: 'string' }, why_not_just_ask: { type: 'string' },
          mechanics: { type: 'string' }, component_types: { type: 'array', items: { type: 'string' } },
          risks: { type: 'string' }, merged_from: { type: 'array', items: { type: 'string' } },
        },
      },
    },
  },
}
const deduped = await agent(`${CONTEXT}\n\nHere are ${allIdeas.length} skill ideas from 5 ideators. Merge duplicates/overlaps into single stronger ideas (combine the best mechanics of each). Keep distinct ideas separate. Do NOT filter for quality yet — only merge. Preserve all fields, list merged_from names.\n\n${JSON.stringify(allIdeas, null, 2)}`,
  { label: 'dedup', phase: 'Dedup', schema: DEDUP_SCHEMA })

log(`${deduped.merged.length} distinct ideas after merge. Judging each adversarially...`)

phase('Judge')
const VERDICT_SCHEMA = {
  type: 'object',
  required: ['passes_bar', 'utility_score', 'feasibility_score', 'critique'],
  properties: {
    passes_bar: { type: 'boolean', description: 'Does it survive the "could I just ask Claude" test?' },
    utility_score: { type: 'number', description: '1-10, real recurring value to a developer' },
    feasibility_score: { type: 'number', description: '1-10, buildable on documented dd-cli surface + local files' },
    critique: { type: 'string', description: 'Sharpest honest critique + one improvement that would raise the score' },
  },
}
const judged = await parallel(deduped.merged.map(idea => () =>
  agent(`${CONTEXT}\n\nYou are an adversarial judge. Your default stance: REJECT. The idea below claims to be a worthwhile dd-cli skill for the aitmpl catalog.\n\nApply three tests:\n1. THE BAR: If a user just told Claude "use dd-cli to do X", would Claude achieve the same outcome without this skill? If yes → fails.\n2. RECURRING UTILITY: Would a real developer use this more than twice, or is it a demo/gimmick?\n3. FEASIBILITY: Buildable with documented commands (search/cart/order/login) + local files + existing component types (skill/loop/hook/command)? Penalize dependence on undocumented commands, other users' data, or APIs dd-cli does not expose.\n\nIDEA:\n${JSON.stringify(idea, null, 2)}\n\nBe harsh but fair. Return your verdict.`,
    { label: `judge:${idea.name}`, phase: 'Judge', schema: VERDICT_SCHEMA })
    .then(v => v ? { ...idea, verdict: v } : null)
))

const survivors = judged.filter(Boolean).filter(i => i.verdict.passes_bar)
log(`${survivors.length}/${deduped.merged.length} ideas passed the adversarial bar. Synthesizing...`)

phase('Synthesize')
const FINAL_SCHEMA = {
  type: 'object',
  required: ['shortlist', 'rejected_summary'],
  properties: {
    shortlist: {
      type: 'array',
      items: {
        type: 'object',
        required: ['rank', 'name', 'pitch', 'why_it_wins', 'build_plan', 'component_types', 'effort'],
        properties: {
          rank: { type: 'number' }, name: { type: 'string' }, pitch: { type: 'string' },
          why_it_wins: { type: 'string' }, build_plan: { type: 'string', description: 'concrete file/component plan' },
          component_types: { type: 'array', items: { type: 'string' } },
          effort: { type: 'string', description: 'S/M/L' },
        },
      },
    },
    rejected_summary: { type: 'string', description: 'One paragraph: what got cut and why' },
  },
}
const final = await agent(`${CONTEXT}\n\nThese ideas survived adversarial judging (with scores and critiques attached). Produce a ranked shortlist of AT MOST 5 for the aitmpl catalog. Rank by (utility x feasibility), apply each judge's suggested improvement to sharpen the idea, and write a concrete build_plan for each (which component types, which files, what state, what dd-cli commands). Also summarize what was rejected and why.\n\nSURVIVORS:\n${JSON.stringify(survivors, null, 2)}\n\nALSO REJECTED EARLIER (for the rejected_summary):\n${JSON.stringify(judged.filter(Boolean).filter(i => !i.verdict.passes_bar).map(i => ({ name: i.name, critique: i.verdict.critique })), null, 2)}`,
  { label: 'synthesize', phase: 'Synthesize', schema: FINAL_SCHEMA })

return { totalRaw: allIdeas.length, afterDedup: deduped.merged.length, passedBar: survivors.length, final }

